import {LEVELS,PROVERBS,QUESTIONS,SKILLS,REFLECTIONS,PRACTICE,plain} from './data.js';
import {grade,total,completed,badges,rankRows,skillStats,same} from './scoring.js';
import {Adventure, paintPostcard} from './adventure.js';
import {speakMalay,stopMalay,audioStatus} from './audio.js';
import {PLACES,CLUES,TRANSFORMS,PASSPORT,WORLD_UI,HELP_STEPS} from './journey-data.js';
import {icon} from './icons.js';
const $=s=>document.querySelector(s),main=$('#main'),dialog=$('#dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readStore=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}};
let storageOK=true;const put=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{storageOK=false;}};
const saved=readStore('lambobudi-dunia-v3',null);
let S=saved?.version===3?saved:{version:3,screen:'home',name:'',car:'red',attempts:{},reflections:{},completedLevels:[],raceDone:[],stars:0,level:0,qIndex:0,panel:0};
let settings={syllables:true,font:24,spacing:1.7,bg:'cream',reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,auto:false,sound:true,rate:.85,...readStore('lambobudi-settings-v3',{})};
let scene='home',race=null,racePaused=false,feedback=null,sequence=[],bonusIndex=0,reflectionIndex=0,practiceIndex=0,practiceItems=[],practiceTries={},teacherKey='',teacherCode='',teacherData=null,boardData=null,syncChain=Promise.resolve(),audioContext=null;
let dialogEngine=null,dialogWasActive=false,readingRefresh=false,storageWarned=false;
let taskPositions={},storyPage=0,toastTimer=null,autoChoice=false,journeyRead=[],arrival=false;
const stopIndex=()=>S.raceDone.includes(S.level)?Math.min(5,LEVELS[S.level].questions.filter(q=>grade(q,S.attempts[q.id])>0).length+1):0;
const CAR_NAMES={red:'Bara',teal:'Bayu',gold:'Suria'};
const skillSymbols={baca:icon('book'),perbuatan:icon('sweep'),nilai:icon('heart'),alasan:icon('friends')};
const words=new Map();
JSON.stringify([LEVELS,PROVERBS]).match(/[\p{L}]+(?:\|[\p{L}]+)+/gu)?.forEach(w=>words.set(plain(w).toLowerCase(),w.toLowerCase()));
function syll(text){const output=String(text).split(/([\p{L}|]+)/u).map(w=>{if(!/[\p{L}]/u.test(w))return esc(w);let marked=w.includes('|')?w:words.get(w.toLowerCase())||w;if(w[0]===w[0]?.toUpperCase())marked=marked[0].toUpperCase()+marked.slice(1);if(!settings.syllables||!marked.includes('|'))return esc(plain(w));return `<span class="word">${marked.split('|').map(s=>`<span class="syllable">${esc(s)}</span>`).join('')}</span>`;}).join('');return `<span class="syllable-text"><span class="sr-only">${esc(plain(text))}</span><span aria-hidden="true">${output}</span></span>`;}
const btn=(action,label,attrs='',style='')=>`<button class="button ${style}" data-action="${action}" ${attrs}>${label}</button>`;
const audioBtn=(text,label='Dengar',className='audio-btn')=>`<button class="${className}" data-audio="${esc(plain(text))}" aria-label="${esc(label)}"><svg class="speaker-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9h4l5-4v14l-5-4H4zM16 8q5 4 0 8M19 5q8 7 0 14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>${className==='answer-audio'?'':` ${esc(label)}`}</button>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6000);}
function save(){put('lambobudi-dunia-v3',S);if(!storageOK&&!storageWarned){storageWarned=true;toast('Pelayar tidak dapat menyimpan kemajuan. Kekalkan tab ini terbuka sehingga selesai.');}}
function applySettings(){document.documentElement.style.setProperty('--readsize',settings.font+'px');document.documentElement.style.setProperty('--readline',settings.spacing);document.documentElement.style.setProperty('--read-bg',({cream:'#fffdf5',blue:'#edf6fb',white:'#ffffff'})[settings.bg]);document.body.classList.toggle('reduced-motion',settings.reduced);put('lambobudi-settings-v3',settings);}
function speak(text,button){if(race?.active)race.pause();speakMalay(plain(text),{rate:Number(settings.rate),notify:toast,button});}
function stopSpeech(){stopMalay();}
function chime(good=true){if(!settings.sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();(good?[523,659,784]:[392]).forEach((frequency,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+i*.1;o.frequency.value=frequency;o.type='sine';g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.04,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+.2);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.22);});}catch{}}
function frame(html){stopSpeech();main.innerHTML=html;window.scrollTo({top:0,behavior:'instant'});const h=main.querySelector('h1,h2');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
function navigate(next){stopSpeech();if(race){race.destroy();race=null;}scene=next;document.body.dataset.scene=next;S.screen=next;save();({home:home,map:map,race:raceScreen,story:story,task:task,reward:reward,bonus:bonus,results:results,reflection:reflection,practice:practice,teacher:teacher})[next]();}
async function api(body){if(location.protocol==='file:'||window.BACANI_PREVIEW)throw new Error('Mod kelas diaktifkan selepas projek diterbitkan di Netlify. Pilih latihan individu untuk mencuba sekarang.');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const r=await fetch('/.netlify/functions/classroom',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:controller.signal});let result;try{result=await r.json();}catch{throw new Error('Simpanan kelas belum tersedia. Pastikan seluruh projek diterbitkan melalui GitHub ke Netlify.');}if(!r.ok)throw new Error(result.error||'Permintaan belum berjaya.');return result;}catch(e){if(e.name==='AbortError')throw new Error('Sambungan mengambil masa. Semak Internet dan cuba lagi.');throw e;}finally{clearTimeout(timeout);}}
function localRow(){return {id:S.localId,name:S.name,car:S.car,score:total(S.attempts),done:completed(S.attempts)===20,level:S.completedLevels.length,badges:badges(S.attempts),reflections:S.reflections};}
function updateLocal(){if(!S.localId)return;let rows=readStore('lambobudi-dunia-roster-v3',[]).filter(r=>r.id!==S.localId);rows.push(localRow());put('lambobudi-dunia-roster-v3',rows.slice(-100));}
function sync(){updateLocal();if(!S.code||!S.auth)return Promise.resolve(true);const snapshot={action:'progress',code:S.code,id:S.auth.id,token:S.auth.token,attempts:structuredClone(S.attempts),reflections:structuredClone(S.reflections)},id=S.localId;S.syncMessage='Sedang menghantar keputusan…';save();syncChain=syncChain.catch(()=>{}).then(async()=>{try{await api(snapshot);if(S.localId===id){S.syncMessage='Keputusan kelas sudah disimpan.';S.pendingSync=false;save();}return true;}catch(e){if(S.localId===id){S.pendingSync=true;S.syncMessage=e.message;save();}return false;}});return syncChain;}
function openDialog(html){stopSpeech();if(!dialog.open){dialogEngine=race;dialogWasActive=!!race?.active;readingRefresh=false;}race?.pause();$('#dialog-content').innerHTML=`<div class="help-audio-tools">${btn('stop-audio','Henti suara','','light small')}${btn('close-dialog','Tutup','','light small')}</div>`+html;const title=$('#dialog-content h2');if(title){title.id='dialog-title';title.tabIndex=-1;dialog.setAttribute('aria-labelledby','dialog-title');}if(!dialog.open)dialog.showModal();dialog.scrollTop=0;title?.focus({preventScroll:true});}
function closeDialog(){const engine=dialogEngine,resume=dialogWasActive;dialog.close();stopSpeech();if(readingRefresh&&['story','task','bonus','practice'].includes(scene)){if(scene==='task')task({keepView:true});else({story,bonus,practice})[scene]();}if(race&&(race===engine||readingRefresh)&&!race.arrived){if(resume&&!feedback){resumeAdventure();}else race.pause();}dialogEngine=null;dialogWasActive=false;readingRefresh=false;}
function resumeAdventure(){stopSpeech();if(!race)return;race.resume();if(settings.auto&&!race.choiceMode&&!race.arrived)race.guide();pauseUI(!race.active);}
function pauseUI(paused=true){racePaused=paused;const b=$('[data-action="pause"]');if(b){b.textContent=paused?'▶ Sambung':'Ⅱ Jeda';b.setAttribute('aria-pressed',String(paused));}}
function journey(){const progress=Math.round(completed(S.attempts)/20*100);return `<div class="active-journey"><img src="assets/car-${S.car}.svg" alt="Kereta ${CAR_NAMES[S.car]}"><b>${esc(S.name)}</b><div class="progress-line" role="progressbar" aria-label="Kemajuan misi" aria-valuenow="${progress}" aria-valuemin="0" aria-valuemax="100"><span style="width:${progress}%"></span></div><span>${completed(S.attempts)}/20 misi</span><span class="chip orange">${total(S.attempts)} mata</span></div>`;}
function home(){const hasResume=S.name&&S.localId;frame(`<section class="fantasy-hero"><div class="hero-mist"></div><div class="fantasy-copy"><span class="journey-kicker">BAHASA MELAYU · TAHUN 3</span><h1>Misi <span>Budi</span></h1><div class="world-edition">Dunia BaCaNi</div><p>Jelajah cerita.<br>Hidupkan budi.</p><div class="hero-chips"><span>4 dunia ajaib</span><span>20 misi bermakna</span></div><div class="hero-kart kart-${S.car}" aria-hidden="true"></div><div class="hero-path-note">Pandu · Teroka · Bantu</div></div><form id="start-form" class="adventure-start"><span class="eyebrow">PASPORT PENGEMBARA</span><h2>Jom mula!</h2><label class="field-label" for="player-name">Siapa nama kamu?</label><input class="input" id="player-name" name="name" maxlength="30" required placeholder="Nama panggilan" autocomplete="off"><label class="field-label car-label">Pilih kereta kamu</label><div class="car-choices" role="group" aria-label="Pilih kereta">${Object.entries(CAR_NAMES).map(([c,n])=>`<button type="button" class="car-choice" data-action="car" data-car="${c}" aria-pressed="${c===S.car}"><span class="mini-kart kart-${c}" aria-hidden="true"></span><span>${n}</span></button>`).join('')}</div><button type="button" class="class-toggle" data-action="class-toggle">Saya ada kod kelas</button><div id="class-fields" class="class-fields" hidden><label class="field-label" for="class-code">Kod kelas</label><input id="class-code" class="input" maxlength="8" placeholder="Kod daripada guru" autocapitalize="characters" autocomplete="off"></div><p id="start-error" class="error" role="alert" hidden></p><button class="button teal" id="start-submit" type="submit">Mulakan pengembaraan →</button><p class="start-note">Tiada had masa. Ikut rentak kamu.</p>${hasResume?btn('resume',`Sambung perjalanan ${esc(S.name)}`,'','outline small'):''}</form></section><div class="learn-strip"><div class="strip-intro">Setiap laluan terbuka<br>apabila kita belajar.</div><div><span class="step-pill">Ba</span><div><b>Baca cerita</b><p>Dengar dan fahami cerita.</p></div></div><div><span class="step-pill">Ca</span><div><b>Cari perbuatan watak</b><p>Pandu untuk memilih bukti.</p></div></div><div><span class="step-pill">Ni</span><div><b>Nilai murni</b><p>Bina jambatan dengan ilmu.</p></div></div></div><div class="home-extra">${btn('help','Cara mengembara','','light small')}${audioBtn(WORLD_UI.welcome,'Dengar sambutan')}${btn('settings','Bantuan bacaan','','outline small')}</div>`);}

async function start(form){const submit=$('#start-submit');const name=$('#player-name').value.trim();if(!name){$('#player-name').focus();return;}const code=$('#class-fields').hidden?'':$('#class-code').value.trim().toUpperCase();submit.disabled=true;submit.textContent='Bersedia…';$('#start-error').hidden=true;let auth=null;try{if(code){if(!/^[A-Z2-9]{8}$/.test(code))throw new Error('Kod kelas mempunyai lapan huruf atau nombor. Semak dengan guru.');auth=await api({action:'join',code,name,car:S.car});}const car=S.car;S={version:3,screen:'map',localId:crypto.randomUUID?.()||String(Date.now())+Math.random(),name:name.slice(0,30),car,code,auth,attempts:{},reflections:{},completedLevels:[],raceDone:[],stars:0,level:0,qIndex:0,panel:0};save();updateLocal();navigate('map');}catch(e){$('#start-error').textContent=e.message;$('#start-error').hidden=false;submit.disabled=false;submit.textContent='Mula pengembaraan →';}}
function map(){S.completedLevels=LEVELS.flatMap((l,i)=>l.questions.every(q=>grade(q,S.attempts[q.id])>0)?[i]:[]);save();frame(`${journey()}<div class="wrap atlas-wrap"><div class="row between"><div><div class="eyebrow">PETA DUNIA BACANI</div><h1 class="page-title">Ke mana kita, ${esc(S.name)}?</h1><p class="muted">Setiap dunia menyimpan cerita, bukti dan nilai.</p></div>${btn('passport','Pasport Budi','','light small')}</div><div class="fantasy-atlas"><div class="atlas-heading">Pengembaraan kamu bermula di sini</div><div class="island-grid">${PLACES.map((p,i)=>{const done=S.completedLevels.includes(i),unlocked=i===0||S.completedLevels.includes(i-1);return `<button class="island ${done?'done':''} ${unlocked?'':'locked'}" data-action="${done?'visit':'level'}" data-level="${i}" ${unlocked?'':'disabled'}><span class="island-number">${done?'✓':i+1}</span><span class="island-art">${p.symbol}</span><b>${p.name}</b><span>${p.focus}</span><small>${done?'Baca semula cerita':unlocked?'Jelajah dunia →':'Buka selepas dunia '+i}</small></button>`;}).join('')}</div><div class="atlas-legend">${S.completedLevels.length}/4 cap dunia dikumpulkan</div></div><div class="mission-cards">${PLACES.map((p,i)=>`<article class="mission-card"><span class="stamp ${S.completedLevels.includes(i)?'earned':''}">${p.symbol}</span><div><b>${p.name}</b><p>${p.goal}</p></div></article>`).join('')}</div><div class="row">${btn('settings','Bantuan bacaan','','light small')}${completed(S.attempts)===20?btn('results','Lihat keputusan →','','teal'):''}<span class="muted">${S.code?`Kod kelas: ${esc(S.code)}`:'Pengembaraan individu'}</span></div></div>`);}

function raceScreen(){const l=LEVELS[S.level],place=PLACES[S.level];const solved=l.questions.filter(q=>grade(q,S.attempts[q.id])>0).length;if(solved===5){navigate('reward');return;}const target=stopIndex(),objective=target===0?WORLD_UI.intro:CLUES[S.level][target-1];arrival=false;frame(`${journey()}<div class="expedition"><div class="expedition-heading"><div><span class="eyebrow">DUNIA ${S.level+1} / 4 · ${place.focus}</span><h1>${place.name}</h1></div><div class="row">${btn('passport','Pasport','','light small')}${btn('map','Peta','','light small')}</div></div><div class="mission-banner"><span class="mission-emblem">${place.symbol}</span><div><small>MISI KITA</small><p id="travel-instruction">${objective}</p></div>${audioBtn(objective,'Dengar misi')}</div><div class="world-shell"><canvas id="race-canvas" tabindex="0" aria-label="Dunia pengembaraan. Anak panah kiri dan kanan untuk bergerak. Ruang untuk melompat. Butang Bantu ke petunjuk juga tersedia."></canvas><div class="world-top"><span class="world-label">${solved}/5 misi selesai</span>${btn('pause','Ⅱ Jeda','','world-button')}</div><div id="arrival-card" class="arrival-card" hidden><span class="eyebrow">HENTIAN PEMBELAJARAN</span><h2>${target===0?'Sebuah cerita menanti.':'Petunjuk ditemukan!'}</h2><p>${target===0?'Baca dan dengar kisah Aina dan Ravi.':'Fahami petunjuk untuk membuka laluan.'}</p>${btn('enter-stop',target===0?'Buka buku cerita':'Mulakan misi','','teal')}</div><div class="world-progress" aria-hidden="true">${['Ba',1,2,3,4,5].map((x,i)=>`<span class="${i<target?'complete':i===target?'current':''}">${i<target?'✓':x}</span>`).join('')}</div></div><div class="control-deck"><div class="drive-controls" aria-label="Kawalan kereta">${driveButtons()}</div><div class="travel-actions">${btn('guide-drive','Bantu ke petunjuk →','','teal small')}${btn('arrive-now','Terus ke hentian','','light small')}</div></div><p class="drive-note">← → Gerak · Ruang: lompat · Tiada had masa · Melompat tidak wajib</p>${solved?`<p class="world-change">✓ ${TRANSFORMS[S.level][solved-1]}</p>`:`<p class="world-change">${place.subtitle}</p>`}</div>`);race=new Adventure($('#race-canvas'),{car:S.car,level:S.level,target,solved,reduced:settings.reduced,cargo:S.level===1&&solved>=2,startPosition:S.positions?.[S.level],onPosition:pos=>{S.positions??={};S.positions[S.level]=pos;save();},onArrive:()=>{arrival=true;$('#arrival-card').hidden=false;$('.travel-actions').hidden=true;const pause=$('[data-action="pause"]');if(pause)pause.disabled=true;chime(true);},onHint:toast,onPause:()=>pauseUI()});racePaused=false;race.start();if(settings.auto)race.guide();bindDrive();}

function driveButtons(){return `<button class="drive-key" data-drive="left" aria-label="Gerak ke kiri">←</button><button class="drive-key" data-drive="right" aria-label="Gerak ke kanan">→</button><button class="drive-key jump-key" data-drive="jump" aria-label="Lompat">↑ <span>Lompat</span></button>`;}
function bindDrive(){for(const control of document.querySelectorAll('[data-drive]')){const release=()=>race?.setKey(control.dataset.drive,false);control.onpointerdown=e=>{e.preventDefault();control.setPointerCapture(e.pointerId);race?.setKey(control.dataset.drive,true);};control.onpointerup=release;control.onpointercancel=release;control.onlostpointercapture=release;control.onclick=e=>{if(e.detail===0){const engine=race;engine?.setKey(control.dataset.drive,true);setTimeout(()=>engine?.setKey(control.dataset.drive,false),240);}};}}
function visual(l){return `<aside class="card story-visual"><div class="story-art scene-${l.image}" role="img" aria-label="${['Aina dan Ravi melihat sampah di taman bersama ibu.','Ravi memegang penyapu ketika Aina berjalan ke arah balai untuk mendapatkan plastik sampah.','Aina dan Ravi berbincang selepas Aina membawa plastik sampah.','Aina dan Ravi membasuh tangan dengan sabun. Ibu membawa buah.'][l.image]}"></div><div class="story-caption"><span class="chip orange">Destinasi ${l.id} · ${l.tag.split(' · ')[0]}</span><h3 style="margin-top:15px">${l.title}</h3><p>${l.goal}</p></div></aside>`;}
function story(){const l=LEVELS[S.level];storyPage=Math.min(storyPage,l.panels.length-1);const line=l.panels[storyPage];frame(`${journey()}<div class="wrap"><div class="row between"><div><div class="eyebrow">Hentian cerita · Enjin berehat</div><h2>Baca dan bayangkan.</h2></div>${btn('map','Peta','','light small')}</div><div class="lesson-layout">${visual(l)}<section class="read-area"><div class="row between"><span class="chip">Bahagian ${storyPage+1} / ${l.panels.length}</span>${audioBtn(line,'Dengar cerita')}</div><div class="reading" style="min-height:170px;margin-top:25px">${syll(line)}</div><div class="page-dots" aria-hidden="true">${l.panels.map((_,i)=>`<span class="${i===storyPage?'active':''}"></span>`).join('')}</div><div class="row">${btn('story-prev','← Kembali',storyPage===0?'disabled':'','light')}${btn('story-next',storyPage===l.panels.length-1?'Teruskan pengembaraan →':'Cerita seterusnya →','','teal')}</div><p class="muted" style="font-size:13px;margin-top:22px;margin-bottom:0">Ambil masa kamu. Kamu boleh mendengar dan membaca semula.</p></section></div></div>`);}
function showStory(level=S.level){const l=LEVELS[level];openDialog(`<h2>${l.title}</h2>${audioBtn(l.panels.join(' '),'Dengar semua')}<div class="all-story reading">${l.panels.map(p=>`<p>${syll(p)}</p>`).join('')}</div>`);}
function answerMarkup(q,tries=[]){if(q.type==='sequence'){return `<p class="muted" style="font-size:15px">Ketik kad satu demi satu mengikut urutan. Nombor menunjukkan pilihan kamu.</p><div class="sequence-preview" aria-label="Urutan pilihan kamu">${sequence.length?sequence.map((n,i)=>`<span class="seq-pill">${i+1}. ${esc(plain(q.options[n].text))}</span>`).join(''):'Pilih peristiwa pertama di bawah.'}</div><div class="answer-list">${q.options.map((o,i)=>`<div class="answer-row"><button class="answer ${sequence.includes(i)?'selected':''}" data-action="sequence" data-index="${i}" ${sequence.includes(i)||feedback?'disabled':''}><span class="option-letter">${sequence.includes(i)?sequence.indexOf(i)+1:'+'}</span><span class="reading">${syll(o.text)}</span></button>${audioBtn(o.text,'Dengar peristiwa '+(i+1),'answer-audio')}</div>`).join('')}</div><div class="row" style="margin-top:18px">${btn('seq-reset','Susun semula',feedback?'disabled':'','light small')}${btn('seq-submit','Semak urutan',sequence.length!==q.options.length||feedback?'disabled':'','teal small')}</div>`;}
return `<div class="answer-list ${q.type==='picture'?'picture-answers':''}">${q.options.map((o,i)=>{const chosen=feedback&&same(feedback.choice,i);const triedWrong=tries.includes(i)&&i!==q.answer;return `<div class="answer-row"><button class="answer ${chosen?(feedback.good?'correct':'wrong'):''}" data-action="answer" data-index="${i}" ${feedback||triedWrong?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span>${o.icon?icon(o.icon):''}<span class="reading">${syll(o.text)}</span></button>${audioBtn(o.text,'Dengar pilihan '+String.fromCharCode(65+i),'answer-audio')}</div>`;}).join('')}</div>`;}
function feedbackMarkup(q){if(!feedback)return '';return `<div class="feedback ${feedback.good?'good':''}" role="status" tabindex="-1"><h3>${feedback.good?'✓ Tahniah, tepat!':'Mari lihat petunjuk.'}</h3><p>${esc(feedback.message)}</p>${feedback.good&&scene==='task'?`<div class="change-earned">✦ ${TRANSFORMS[S.level][S.qIndex]}</div>`:''}${q.evidence?`<p class="evidence"><b>Bukti cerita:</b> ${esc(q.evidence)}</p>${audioBtn(q.evidence,'Dengar bukti')}`:''}<div class="row">${audioBtn(feedback.message,'Dengar penerangan')}${feedback.good?btn(scene==='practice'?'practice-next':scene==='bonus'?'bonus-next':'task-next',scene==='bonus'?'Kad seterusnya →':scene==='task'?'Sambung pengembaraan →':'Teruskan →','','teal small'):btn('retry','Cuba lagi','','light small')}</div></div>`;}
function task({keepView=false,worldFocus=false}={}){const scrollY=window.scrollY,wasPaused=!!race&&!race.active&&!race.locked;if(race){race.destroy();race=null;}const l=LEVELS[S.level],q=l.questions[S.qIndex],tries=S.attempts[q.id]||[],isSeq=q.type==='sequence';const instruction=isSeq?WORLD_UI.sequence:WORLD_UI.collect;frame(`${journey()}<div class="wrap question-screen"><div class="row between"><div><div class="eyebrow">${PLACES[S.level].name} · Misi ${S.qIndex+1} / 5</div><h1 class="mission-title">${CLUES[S.level][S.qIndex]}</h1></div>${btn('show-story','Baca semula cerita','','light small')}</div><section class="question-prompt"><span class="chip">${SKILLS[q.skill]}</span><h2 class="reading">${syll(q.text)}</h2>${audioBtn(q.text,'Dengar soalan')}</section><div class="mission-layout"><div class="mission-play"><div class="world-shell choice-shell"><canvas id="mission-canvas" tabindex="0" aria-label="Pandu ke pilihan A, B atau C. Tekan E untuk memilih. Kad jawapan yang sama tersedia selepas kawasan permainan."></canvas><div class="world-top mission-top">${btn('pause','Ⅱ Jeda',feedback?'disabled':'','world-button')}</div><span class="scene-label">${isSeq?'Bina laluan cerita':q.id==='l2q2'?'Pilih bekalan untuk Aina':q.id==='l1q3'?'Cari benda yang mengotorkan taman':'Pandu ke petunjuk pilihan kamu'}</span></div><div class="control-deck"><div class="drive-controls">${driveButtons()}</div>${btn('interact','Pilih (E)','id="pick-near" disabled','teal small')}</div><p class="drive-note">${instruction} ${audioBtn(instruction,'Dengar panduan')}</p>${isSeq?`<div class="bridge-progress" aria-label="${sequence.length} daripada 3 peristiwa dipilih">${[0,1,2].map((_,i)=>`<span class="${i<sequence.length?(feedback?.good?'built':'placed'):''}">${i<sequence.length&&feedback?.good?'✓':i+1}</span>`).join('')}</div>`:''}<div id="near-choice" class="near-choice" aria-live="polite"><p>Pandu dekat pilihan untuk melihat dan mendengar petunjuknya.</p></div><div class="row">${btn('answer-cards','Terus ke kad jawapan ↓','','light small')}</div><div class="evidence-note">${icon('book')}<p>Jawapan membuka laluan apabila sepadan dengan cerita. Gunakan butang “Baca semula cerita” jika perlu.</p></div></div><section class="task-card mission-answers"><div class="row between"><h3>${isSeq?'Susun peristiwa':'Pilih jawapan kamu'}</h3><span class="chip">Boleh ketik kad</span></div>${answerMarkup(q,tries)}${feedbackMarkup(q)}<div class="row" style="margin-top:18px">${btn('map','Simpan & kembali ke peta','','outline small')}</div></section></div></div>`);const picked=feedback?.good&&!isSeq?[feedback.choice]:sequence;race=new Adventure($('#mission-canvas'),{mode:'choice',car:S.car,level:S.level,solved:l.questions.filter(v=>grade(v,S.attempts[v.id])>0).length,sequenceMode:isSeq,options:q.options,selected:picked,disabled:isSeq?[]:tries.filter(i=>i!==q.answer),success:!!feedback?.good,locked:!!feedback,reduced:settings.reduced,startPosition:taskPositions[q.id],onPosition:p=>taskPositions[q.id]=p,onChoice:i=>{if(feedback)return;if(isSeq){if(!sequence.includes(i)){sequence.push(i);task({keepView:true,worldFocus:true});}}else submitAnswer(i);},onNear:i=>{const near=$('#near-choice');if(near)near.innerHTML=i<0?'<p>Pandu dekat pilihan untuk melihat dan mendengar petunjuknya.</p>':`<small>PILIHAN ${String.fromCharCode(65+i)} DI HADAPAN KAMU</small><p class="reading">${syll(q.options[i].text)}</p>${audioBtn(q.options[i].text,'Dengar pilihan berdekatan')}`;const b=$('#pick-near');if(b){b.disabled=i<0||!!feedback||picked.includes(i)||(!isSeq&&tries.includes(i));b.textContent=i<0?'Pandu dekat pilihan':`Pilih ${String.fromCharCode(65+i)} (E)`;}},onHint:toast,onPause:()=>pauseUI()});racePaused=false;race.start();if(wasPaused&&!feedback)race.pause();bindDrive();if(keepView)window.scrollTo({top:scrollY,behavior:'instant'});if(worldFocus&&!feedback)$('#mission-canvas').focus({preventScroll:true});if(feedback)main.querySelector('.feedback').focus();}
function activeQuestion(){return scene==='bonus'?PROVERBS[bonusIndex]:scene==='practice'?practiceItems[practiceIndex]:LEVELS[S.level].questions[S.qIndex];}
function submitAnswer(choice){if(feedback)return;const q=activeQuestion(),attempts=scene==='practice'?practiceTries:S.attempts;attempts[q.id]??=[];if(attempts[q.id].some(a=>same(a,q.answer)))return;if(attempts[q.id].length>=11&&!same(choice,q.answer)){toast('Lihat petunjuk dan pilih jawapan yang sepadan dengan cerita.');return;}attempts[q.id].push(structuredClone(choice));const good=same(choice,q.answer);let message;if(q.type==='sequence'){const mismatch=choice.findIndex((v,i)=>v!==q.answer[i]);message=good?'Ya! Urutan kamu mengikut peristiwa dalam cerita.':`Pada tempat ${mismatch+1}, kamu memilih “${plain(q.options[choice[mismatch]].text)}”. Pada tempat itu, peristiwa yang sepadan ialah “${plain(q.options[q.answer[mismatch]].text)}”. Baca semula urutan cerita.`;}else message=q.options[choice].why;feedback={choice,good,message};if(scene==='task'&&LEVELS[S.level].questions.every(item=>grade(item,S.attempts[item.id])>0)&&!S.completedLevels.includes(S.level))S.completedLevels.push(S.level);if(scene!=='practice')save();chime(good);if(scene==='bonus')bonus();else if(scene==='practice')practice();else task();}
function nextTask(){feedback=null;sequence=[];stopSpeech();if(S.qIndex<4){S.qIndex++;save();sync();navigate('race');}else{if(!S.completedLevels.includes(S.level))S.completedLevels.push(S.level);save();sync();navigate('reward');}}
function confetti(){if(settings.reduced)return '';return `<div class="confetti" aria-hidden="true">${Array.from({length:20},(_,i)=>`<i style="left:${i*5}%;background:${['#e77954','#71b599','#e7bd4d','#88afd3'][i%4]};animation-delay:${i*.07}s"></i>`).join('')}</div>`;}
function reward(){const l=LEVELS[S.level],p=PASSPORT[S.level],score=l.questions.reduce((n,q)=>n+grade(q,S.attempts[q.id]),0);frame(`${journey()}<div class="wrap"><section class="finish-card">${confetti()}<span class="stamp earned big-stamp">${PLACES[S.level].symbol}</span><span class="eyebrow">DESTINASI ${S.level+1} SELESAI</span><h1 class="page-title">${PLACES[S.level].celebrate}</h1><p>Tahniah, ${esc(S.name)}! Teruskan usaha.</p><canvas id="restored-canvas" class="restored-canvas" aria-label="Bandar selepas petunjuk diselesaikan"></canvas><div class="passport-entry"><p><b>Ba · Baca cerita</b><br>${p.baca}</p><p><b>Ca · Cari perbuatan watak</b><br>${p.cari}</p><p><b>Ni · Nilai murni</b><br>${p.nilai}</p></div>${audioBtn(`${p.baca} ${p.cari} ${p.nilai}`,'Dengar rumusan')}<p class="mission-score">${score}/25 mata pembelajaran</p><div class="row">${S.level<3?btn('next-level','Jelajah destinasi seterusnya →','','teal'):btn('bonus-start','Buka khazanah peribahasa','','teal')}${btn(S.level<3?'map':'results',S.level<3?'Lihat peta':'Lihat keputusan','','light')}</div></section></div>`);paintPostcard($('#restored-canvas'),{level:S.level,solved:5,car:S.car});chime(true);}
function passport(){openDialog(`<span class="eyebrow">PASPORT BUDI</span><h2>Jejak pembelajaran saya</h2><p>Setiap cap menyimpan cerita, perbuatan dan nilai yang telah kita pelajari.</p>${PASSPORT.map((p,i)=>`<section class="passport-entry ${S.completedLevels.includes(i)?'':'passport-locked'}"><h3>${PLACES[i].symbol} ${PLACES[i].name}</h3>${S.completedLevels.includes(i)?`<p><b>Ba:</b> ${p.baca}</p><p><b>Ca:</b> ${p.cari}</p><p><b>Ni:</b> ${p.nilai}</p>${audioBtn(`${p.baca} ${p.cari} ${p.nilai}`,'Dengar catatan')}`:'<p>Selesaikan destinasi ini untuk membuka catatannya.</p>'}</section>`).join('')}`);}

function bonus(){const p=PROVERBS[bonusIndex];if(!p){navigate('results');return;}frame(`${journey()}<div class="wrap"><section class="card bonus-card"><div class="row between"><span class="chip orange">Bonus ${bonusIndex+1} / 5 · ${p.type}</span>${btn('results','Keputusan →','','light small')}</div><div class="proverb reading">${syll(p.text)}</div>${audioBtn(`${plain(p.text)}. Maksudnya, ${p.meaning}. ${p.context}`,'Dengar kad')}<div class="meaning"><b>Maksud:</b> ${esc(p.meaning)}</div><p style="font-size:19px">${esc(p.context)}</p><h3>Apakah tindakan yang sesuai dengan peribahasa ini?</h3>${answerMarkup(p,S.attempts[p.id]||[])}${feedbackMarkup(p)}<div class="row between" style="margin-top:20px"><a href="${p.source}" target="_blank" rel="noopener noreferrer" style="font-size:12px">Rujukan PRPM ↗</a>${btn('bonus-skip','Langkau kad ini','','outline small')}</div><p class="muted" style="font-size:12px;margin:12px 0 0">Bonus memberikan lencana tambahan. Skor utama kekal daripada 100 mata.</p></section></div>`);}
function rowTable(rows,teacherMode=false){if(!rows.length)return '<p class="notice">Belum ada peserta dalam sesi ini.</p>';return `<div class="table-wrap"><table><thead><tr><th scope="col">Kedudukan</th><th scope="col">Pengembara</th><th scope="col">Skor</th><th scope="col">Lencana</th>${teacherMode?'<th scope="col">Kemajuan & refleksi</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr class="${r.id===(S.auth?.id||S.localId)?'me':''}"><td>${r.rank??'—'}</td><td><b>${esc(r.name)}</b><br><small>${r.done?'Empat destinasi selesai':`Belum tamat · ${r.level}/4 destinasi`}</small></td><td>${r.score}/100</td><td>★ ${r.badges}/5</td>${teacherMode?`<td><details class="teacher-detail"><summary>Lihat rekod</summary><p>${Object.entries(r.skills||{}).map(([k,v])=>`${SKILLS[k]}: ${v.first}/${v.total} tepat pada cubaan pertama; ${v.solved}/${v.total} selesai selepas bimbingan.`).join('<br>')}</p><p>${REFLECTIONS.map(q=>{const val=q.items.find(([id])=>id===r.reflections?.[q.id]);return `${esc(q.title)} <b>${val?esc(val[1]):'Belum diisi'}</b>`;}).join('<br>')}</p></details></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function podium(rows){return `<div class="podium">${rows.filter(r=>r.done).slice(0,3).map(r=>`<div class="podium-person"><img src="assets/car-${r.car}.svg" alt=""><b>${esc(r.name)}</b><small>${r.score}/100 mata</small><div class="podium-step">${r.rank===1?'🏆 ':''}${r.rank}</div></div>`).join('')}</div>`;}
function fillBoard(data){boardData=data;const holder=$('#leaderboard-content');if(!holder)return;holder.innerHTML=`<p class="muted" style="font-size:14px">${esc(data.name)} · <b>${data.closed?'Kedudukan akhir':'Kedudukan sementara'}</b></p>${podium(data.rows)}${rowTable(data.rows)}<p class="muted" style="font-size:12px;margin-top:14px">Skor sama mendapat kedudukan yang sama. Peserta yang belum tamat belum diberi kedudukan.</p>`;}
async function fetchBoard(){const holder=$('#leaderboard-content');if(!holder)return;if(!S.code){fillBoard({name:'Peserta pada peranti ini',closed:true,rows:rankRows(readStore('lambobudi-dunia-roster-v3',[]))});return;}holder.innerHTML='<div class="loading">Memuatkan kedudukan kelas…</div>';try{const data=await api({action:'leaderboard',code:S.code});if(scene==='results')fillBoard(data);}catch(e){if(scene==='results')holder.innerHTML=`<div class="notice">${esc(e.message)}<p>Skor kamu tetap disimpan pada peranti ini.</p>${btn('refresh-board','Cuba lagi','','light small')}</div>`;}}
function results(){updateLocal();const stats=skillStats(S.attempts),strength=Object.entries(stats).sort((a,b)=>b[1].first/b[1].total-a[1].first/a[1].total)[0]?.[0]||'baca';frame(`<div class="wrap"><div class="row between"><div><div class="eyebrow">Pengembaraan selesai · Dunia BaCaNi</div><h1 style="font-size:48px">Tahniah, ${esc(S.name)}!</h1><p>Kamu telah membantu di empat destinasi. <b>Teruskan usaha!</b></p></div><span class="trophy-icon" aria-hidden="true">${icon('trophy')}</span></div><div class="results-layout"><section class="card"><div class="row between"><h2 style="font-size:27px">Keputusan kamu</h2><span class="chip orange">★ ${badges(S.attempts)}/5 bonus</span></div><div class="score-orb">${total(S.attempts)}<small>/100 mata</small></div><div class="stat-grid">${LEVELS.map(l=>`<div class="stat"><strong>${l.questions.reduce((n,q)=>n+grade(q,S.attempts[q.id]),0)}/25</strong><span>Destinasi ${l.id}</span></div>`).join('')}</div><p>Kamu paling konsisten dalam <b>${SKILLS[strength].toLowerCase()}</b>. Mari pilih kemahiran untuk dilatih seterusnya.</p><div class="row">${btn('reflection-start','💬 Refleksi saya →','','teal')}${btn('bonus-start','Kad peribahasa','','light')}</div><p id="sync-note" class="muted" role="status" style="font-size:12px;margin-top:18px">${esc(S.code?(S.syncMessage||'Menghantar keputusan kelas…'):'Keputusan disimpan pada pelayar peranti ini.')}</p>${S.code?btn('resync','Hantar semula keputusan','','outline small'):''}</section><section class="card"><div class="row between"><h2 style="font-size:27px">Papan kedudukan</h2>${btn('refresh-board','↻ Muat semula','','light small')}</div><div id="leaderboard-content"></div></section></div><div class="row" style="margin-top:22px">${btn('practice-start','Latih kemahiran saya','','light')}${btn('home','Muka hadapan','','outline')}</div></div>`);sync().then(()=>{if(scene==='results'){const note=$('#sync-note');if(note)note.textContent=S.syncMessage||'Keputusan disimpan pada peranti ini.';fetchBoard();}});}
function reflection(){const r=REFLECTIONS[reflectionIndex];if(!r){sync();startPractice();return;}const selected=S.reflections[r.id];frame(`<div class="wrap reflection-box"><div class="eyebrow">Garaj refleksi · ${reflectionIndex+1} / 4</div><h1 style="font-size:43px">Kenali kemajuanmu.</h1><p class="muted">Pilih jawapan yang menggambarkan diri kamu. Refleksi tidak menambah atau mengurangkan skor.</p><section class="card"><div class="row between"><h2 style="font-size:28px">${r.title}</h2>${audioBtn(r.title,'Dengar soalan')}</div><div class="reflection-options">${r.items.map(([id,text],i)=>`<button class="reflection-option ${selected===id?'selected':''}" data-action="reflect" data-value="${id}" aria-pressed="${selected===id}"><span class="reflection-icon" aria-hidden="true">${skillSymbols[id]||['📖','🔊','🔎','💬'][i]}</span><span>${esc(text)}</span></button>`).join('')}</div><div class="row" style="margin-top:18px">${audioBtn(r.items.map(([,t])=>t).join('. '),'Dengar pilihan')}${btn('reflection-next',reflectionIndex===3?'Simpan & berlatih →':'Seterusnya →',selected?'':'disabled','teal')}</div></section><div class="row" style="margin-top:18px">${btn('results','Kembali ke keputusan','','outline small')}</div></div>`);}
function startPractice(){const stats=skillStats(S.attempts),weak=S.reflections.difficulty||Object.entries(stats).sort((a,b)=>a[1].first/a[1].total-b[1].first/b[1].total)[0]?.[0]||'alasan';const first=PRACTICE.find(p=>p.skill===weak)||PRACTICE[0];practiceItems=[first,PRACTICE.find(p=>p.id!==first.id&&p.skill==='alasan')||PRACTICE.find(p=>p.id!==first.id)];practiceIndex=0;practiceTries={};feedback=null;sequence=[];navigate('practice');}
function practice(){if(practiceIndex>=practiceItems.length){S.practiceCompleted=true;save();frame(`<div class="wrap"><section class="finish-card">${confetti()}<span class="trophy-icon">🌟</span><h1 style="font-size:40px">Usaha kamu berharga!</h1><p>Tahniah, ${esc(S.name)}. Kamu telah menyiapkan dua latihan pengukuhan.</p><p><b>Teruskan usaha:</b> baca cerita, cari perbuatan watak, kemudian nyatakan nilai dan buktinya.</p><div class="row">${btn('results','Lihat keputusan','','teal')}${btn('practice-start','Berlatih lagi','','light')}</div></section></div>`);return;}const q=practiceItems[practiceIndex];frame(`<div class="wrap bonus-card"><div class="eyebrow">Latihan pengukuhan · ${practiceIndex+1} / 2</div><h1 style="font-size:42px">Satu langkah lebih yakin.</h1><p class="muted">Latihan ini membantu kamu berlatih ${SKILLS[q.skill].toLowerCase()}. Skor pembelajaran sudah disimpan.</p><section class="task-card">${audioBtn(q.text,'Dengar latihan')}<h2 class="reading">${syll(q.text)}</h2>${answerMarkup(q,practiceTries[q.id]||[])}${feedbackMarkup(q)}</section></div>`);}
function teacher(){frame(`<div class="wrap"><div class="teacher-form"><div class="eyebrow">Ruang guru</div><h1 style="font-size:43px">Satu kelas, satu pengembaraan.</h1><p>Cipta sesi dan berikan kod kepada murid. Keputusan daripada peranti berbeza dikumpulkan dalam sesi yang sama.</p><form id="teacher-form" class="card stack"><div><label class="field-label" for="teacher-key">Kunci guru</label><input class="input" id="teacher-key" type="password" autocomplete="current-password" required placeholder="Kunci yang ditetapkan di Netlify"></div><div class="teacher-grid"><div><label class="field-label" for="room-name">Nama sesi baharu</label><input class="input" id="room-name" maxlength="60" placeholder="Contoh: Tahun 3 Cemerlang"></div><div><label class="field-label" for="teacher-code">Kod sesi sedia ada</label><input class="input" id="teacher-code" maxlength="8" value="${esc(teacherCode)}" placeholder="Lapan huruf / nombor" autocomplete="off"></div></div><p id="teacher-error" class="error" role="alert" hidden></p><div class="row"><button class="button teal" type="submit" name="intent" value="create">Cipta sesi baharu</button><button class="button light" type="submit" name="intent" value="teacher">Buka sesi</button></div><small class="muted">Kunci guru digunakan untuk pengurusan sesi. Murid hanya memerlukan kod kelas.</small></form><p class="notice" style="margin-top:20px">Kali pertama? Ikuti fail PANDUAN.html dalam pakej projek untuk menetapkan KUNCI_GURU di Netlify. Latihan individu boleh digunakan tanpa tetapan ini.</p></div><div id="teacher-dashboard"></div></div>`);if(teacherData)teacherDashboard();}
function teacherDashboard(){const d=teacherData;const container=$('#teacher-dashboard');if(!container)return;container.innerHTML=`<section class="card" style="margin-top:35px"><div class="row between"><div><div class="eyebrow">${esc(d.name)}</div><div class="room-code">${esc(d.code)}</div><p class="muted">${d.closed?'Sesi ditutup · Kedudukan akhir':'Sesi dibuka · Kedudukan sementara'}</p></div><div class="row">${btn('teacher-refresh','↻ Muat semula','','light small')}${btn('teacher-copy','Salin kod','','light small')}${btn('teacher-export','Muat turun CSV','','teal small')}${btn(d.closed?'teacher-open':'teacher-close',d.closed?'Buka semula':'Tutup sesi','','outline small')}</div></div><div class="stat-grid"><div class="stat"><strong>${d.rows.length}</strong><span>Peserta</span></div><div class="stat"><strong>${d.rows.filter(r=>r.done).length}</strong><span>Tamat</span></div><div class="stat"><strong>${d.rows.filter(r=>r.reflections?.habit).length}</strong><span>Refleksi lengkap</span></div><div class="stat"><strong>${d.rows.length?Math.round(d.rows.reduce((s,r)=>s+r.score,0)/d.rows.length):0}</strong><span>Purata skor semasa</span></div></div>${rowTable(d.rows,true)}<p style="font-size:13px;margin-top:20px" class="muted">Skor permainan menyokong pemerhatian guru. Tahap Penguasaan PBD memerlukan pertimbangan guru, termasuk penerangan lisan murid.</p>${btn('teacher-delete','Padam sesi ini','','outline small')}</section>`;}
async function teacherSubmit(form,action){teacherKey=$('#teacher-key').value||teacherKey;teacherCode=$('#teacher-code').value.trim().toUpperCase();const name=$('#room-name').value.trim();$('#teacher-error').hidden=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(action==='create'){const room=await api({action:'create',teacherKey,name:name||'Kelas BaCaNi'});teacherCode=room.code;$('#teacher-code').value=teacherCode;}teacherData=await api({action:'teacher',teacherKey,code:teacherCode});teacherDashboard();$('#teacher-dashboard').scrollIntoView({behavior:settings.reduced?'instant':'smooth'});}catch(e){$('#teacher-error').hidden=false;$('#teacher-error').textContent=e.message;}finally{form.querySelectorAll('button').forEach(b=>b.disabled=false);}}
async function teacherAction(action){try{teacherData=await api({action,teacherKey,code:teacherCode});teacherDashboard();}catch(e){toast(e.message);}}
function exportCSV(){if(!teacherData)return;const safe=x=>{let s=String(x??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const head=['Kedudukan','Nama','Skor /100','Destinasi selesai','Lencana /5',...Object.values(SKILLS).map(s=>s+' (tepat pertama/jumlah)'),...REFLECTIONS.map(r=>r.title)];const rows=teacherData.rows.map(r=>[r.rank??'Belum tamat',r.name,r.score,r.level,r.badges,...Object.keys(SKILLS).map(k=>`${r.skills[k]?.first||0}/${r.skills[k]?.total||0}`),...REFLECTIONS.map(q=>q.items.find(([id])=>id===r.reflections?.[q.id])?.[1]||'Belum diisi')]);download('\ufeff'+[head,...rows].map(r=>r.map(safe).join(',')).join('\r\n'),`Keputusan-BaCaNi-${teacherCode}.csv`,'text/csv;charset=utf-8');}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function help(){openDialog(`<h2>Cara mengembara</h2><p>Pilih satu panduan untuk didengar. Kamu boleh mengulangnya.</p>${HELP_STEPS.map(({title,text},i)=>`<div class="help-step"><b>${i+1}</b><div><p><strong>${title}</strong><br>${esc(text)}</p>${audioBtn(text,`Dengar panduan ${i+1}`)}</div></div>`).join('')}`);}
function settingsDialog(){openDialog(`<h2>Bantuan untuk perjalananmu.</h2><div class="font-sample" aria-label="Contoh huruf a kecil: a, saya, baca, taman">a <span>saya · baca · taman</span></div><p class="muted">Pilih paparan dan kawalan yang selesa. Bantuan tidak mengurangkan skor.</p><div class="setting-row"><label for="set-syllables">Suku kata dua warna<small>Biru tua dan ungu tua berselang.</small></label><input type="checkbox" id="set-syllables" data-setting="syllables" ${settings.syllables?'checked':''}></div><div class="setting-row"><label for="set-font">Saiz tulisan</label><select id="set-font" data-setting="font">${[24,28,32].map(v=>`<option value="${v}" ${Number(settings.font)===v?'selected':''}>${v===24?'Besar':v===28?'Lebih besar':'Sangat besar'}</option>`).join('')}</select></div><div class="setting-row"><label for="set-spacing">Jarak baris</label><select id="set-spacing" data-setting="spacing"><option value="1.7" ${settings.spacing==1.7?'selected':''}>Selesa</option><option value="2" ${settings.spacing==2?'selected':''}>Lebih luas</option></select></div><div class="setting-row"><label for="set-bg">Latar bacaan</label><select id="set-bg" data-setting="bg"><option value="cream" ${settings.bg==='cream'?'selected':''}>Krim lembut</option><option value="blue" ${settings.bg==='blue'?'selected':''}>Biru lembut</option><option value="white" ${settings.bg==='white'?'selected':''}>Putih</option></select></div><div class="setting-row"><label for="set-auto">Pandu automatik<small>Kereta membantu kamu ke petunjuk seterusnya.</small></label><input type="checkbox" id="set-auto" data-setting="auto" ${settings.auto?'checked':''}></div><div class="setting-row"><label for="set-reduced">Kurangkan animasi<small>Hentikan gerakan hiasan dan animasi perjalanan automatik.</small></label><input type="checkbox" id="set-reduced" data-setting="reduced" ${settings.reduced?'checked':''}></div><div class="setting-row"><label for="set-sound">Kesan bunyi</label><input type="checkbox" id="set-sound" data-setting="sound" ${settings.sound?'checked':''}></div><div class="setting-row"><label for="set-rate">Kelajuan bacaan suara</label><select id="set-rate" data-setting="rate"><option value="0.7" ${settings.rate==.7?'selected':''}>Perlahan</option><option value="0.85" ${settings.rate==.85?'selected':''}>Sederhana</option><option value="1" ${settings.rate==1?'selected':''}>Biasa</option></select></div><p class="muted" style="margin:15px 0">${audioStatus()}</p>${audioBtn('Mari kita baca cerita bersama-sama.','Cuba suara Melayu')}`);}
function about(){openDialog(`<div class="about"><h2>Misi Budi</h2><p>Permainan Bahasa Melayu SK Tahun 3. Teknik: Baca cerita, Cari perbuatan watak, Nilai murni. Tema: Kesihatan dan Kebersihan.</p><p><b>DSKP:</b> SK 2.3 dan SP 2.3.1(iii), membaca dan menjelaskan kandungan cerita. Cerita Aina dan Ravi ditulis khusus untuk permainan ini. Kereta membawa murid mengumpulkan petunjuk cerita. Setiap petunjuk yang difahami mengubah bandar dan membuka langkah seterusnya.</p><p>Pautan nilai kepada peribahasa ialah tafsiran pengajaran berdasarkan konteks. Guru boleh menerima nilai lain yang disokong bukti yang sesuai dalam aktiviti lisan.</p><ul class="source-list"><li><a href="https://bukuteksdigital.my/wp-content/uploads/2020/06/DSKP-KSSR-SEMAKAN-2017-BAHASA-MELAYU-TAHUN-3.pdf" target="_blank" rel="noopener">DSKP Bahasa Melayu Tahun 3, halaman bercetak 33</a></li><li><a href="https://online.fliphtml5.com/bhyii/nixx/#p=1" target="_blank" rel="noopener">Buku teks rujukan pengguna</a></li>${PROVERBS.map(p=>`<li><a href="${p.source}" target="_blank" rel="noopener">PRPM: ${plain(p.text)}</a></li>`).join('')}<li><a href="https://www.bdadyslexia.org.uk/advice/employers/creating-a-dyslexia-friendly-workplace/dyslexia-friendly-style-guide" target="_blank" rel="noopener">Panduan paparan British Dyslexia Association</a></li></ul><p><b>Simpanan:</b> latihan individu disimpan pada pelayar ini. Mod kelas menghantar nama panggilan, pilihan jawapan, skor dan refleksi kepada simpanan sesi. Guru boleh memadam sesi.</p><p>Ilustrasi dunia fantasi, watak berkereta dan cerita dijana khusus untuk projek ini. Platform, jambatan, pagar, kawalan dan ikon dibina dalam kod projek. Reka bentuk pengembaraan sisi menggunakan watak asli. Fon Andika oleh SIL Global, berlesen SIL Open Font License, menggunakan huruf a dan g satu tingkat. Bacaan menggunakan rakaman suara sintetik Melayu Malaysia, Yasmin (ms-MY). Suara peranti tidak digunakan sebagai gantian. Teks kekal tersedia bersama bacaan yang boleh diulang, dihentikan dan diperlahankan.</p><p>Permainan ini bahan pembelajaran. Skor bukan diagnosis disleksia atau penetapan automatik Tahap Penguasaan.</p></div>`);}
async function action(name,el){switch(name){
 case 'home':navigate('home');break;
 case 'car':S.car=el.dataset.car;const kart=$('.hero-kart');if(kart)kart.className='hero-kart kart-'+S.car;if($('#welcome-canvas'))paintPostcard($('#welcome-canvas'),{hero:true,car:S.car});main.querySelectorAll('.car-choice').forEach(b=>b.setAttribute('aria-pressed',b.dataset.car===S.car));break;
 case 'class-toggle':$('#class-fields').hidden=!$('#class-fields').hidden;if(!$('#class-fields').hidden)$('#class-code').focus();break;
 case 'resume':navigate(completed(S.attempts)===20?'results':'map');break;
 case 'help':help();break;case 'settings':settingsDialog();break;case 'map':navigate('map');break;
 case 'level':S.level=Number(el.dataset.level);S.qIndex=LEVELS[S.level].questions.findIndex(q=>grade(q,S.attempts[q.id])===0);if(S.qIndex<0)S.qIndex=0;feedback=null;sequence=[];storyPage=0;navigate('race');break;
 case 'review-level':showStory(Number(el.dataset.level));break;
 case 'next-level':S.level++;S.qIndex=0;storyPage=0;feedback=null;sequence=[];navigate('race');break;
 case 'race-start':race?.resume();break;
 case 'guide-drive':race?.resume();pauseUI(false);race?.guide();break;
 case 'arrive-now':race?.arrive();break;
 case 'enter-stop':if(!arrival)return;if(!S.raceDone.includes(S.level)){storyPage=0;navigate('story');}else{S.qIndex=LEVELS[S.level].questions.findIndex(q=>grade(q,S.attempts[q.id])===0);feedback=null;sequence=[];navigate('task');}break;
 case 'passport':passport();break;
 case 'visit':showStory(Number(el.dataset.level));break;
 case 'stop-audio':stopSpeech();break;
 case 'close-dialog':closeDialog();break;
 case 'answer-cards':$('.mission-answers')?.scrollIntoView({behavior:settings.reduced?'instant':'smooth'});$('.mission-answers button:not(:disabled)')?.focus({preventScroll:true});break;
 case 'interact':race?.interact();break;
 case 'steer':race?.steer(Number(el.dataset.dir));break;
 case 'pause':if(!race)return;if(race.active){race.pause();toast('Pengembaraan dijeda.');}else{resumeAdventure();race.canvas.focus({preventScroll:true});}break;
 case 'auto':settings.auto=!settings.auto;applySettings();if(race)race.auto=settings.auto;el.textContent=settings.auto?'✓ Pandu automatik':'Aktifkan pandu automatik';toast(settings.auto?'Pandu automatik diaktifkan.':'Kawalan manual diaktifkan.');break;
 case 'story-prev':stopSpeech();storyPage=Math.max(0,storyPage-1);story();break;
 case 'story-next':stopSpeech();if(storyPage<LEVELS[S.level].panels.length-1){storyPage++;story();}else{if(!S.raceDone.includes(S.level))S.raceDone.push(S.level);feedback=null;sequence=[];save();navigate('race');}break;
 case 'show-story':showStory();break;
 case 'answer':submitAnswer(Number(el.dataset.index));break;
 case 'sequence':if(!feedback&&!sequence.includes(Number(el.dataset.index)))sequence.push(Number(el.dataset.index));if(scene==='practice')practice();else{task({keepView:true});const next=$('[data-action="sequence"]:not(:disabled)')||$('[data-action="seq-submit"]');next?.focus({preventScroll:true});}break;
 case 'seq-reset':sequence=[];scene==='practice'?practice():task({keepView:true});break;
 case 'seq-submit':submitAnswer([...sequence]);break;
 case 'retry':feedback=null;sequence=[];scene==='bonus'?bonus():scene==='practice'?practice():task();break;
 case 'task-next':nextTask();break;
 case 'bonus-start':bonusIndex=PROVERBS.findIndex(p=>!(S.attempts[p.id]||[]).some(a=>same(a,p.answer)));if(bonusIndex<0){openDialog(`<h2>Lima lencana dikumpulkan!</h2><p>Kamu telah melengkapkan semua kad bonus.</p>${PROVERBS.map(p=>`<p><b>${plain(p.text)}</b><br>${p.meaning}</p>`).join('')}`);break;}feedback=null;navigate('bonus');break;
 case 'bonus-next':case 'bonus-skip':feedback=null;bonusIndex++;while(PROVERBS[bonusIndex]&&(S.attempts[PROVERBS[bonusIndex].id]||[]).some(a=>same(a,PROVERBS[bonusIndex].answer)))bonusIndex++;sync();bonus();break;
 case 'results':navigate('results');break;
 case 'refresh-board':fetchBoard();break;
 case 'resync':el.disabled=true;await sync();if(scene==='results'){$('#sync-note').textContent=S.syncMessage;el.disabled=false;fetchBoard();}break;
 case 'reflection-start':reflectionIndex=0;navigate('reflection');break;
 case 'reflect':S.reflections[REFLECTIONS[reflectionIndex].id]=el.dataset.value;save();reflection();break;
 case 'reflection-next':reflectionIndex++;save();reflection();break;
 case 'practice-start':startPractice();break;
 case 'practice-next':practiceIndex++;feedback=null;sequence=[];practice();break;
 case 'local-board':openDialog(`<h2>Kedudukan pada peranti ini</h2><p class="muted">Senarai latihan individu yang disimpan dalam pelayar ini.</p>${rowTable(rankRows(readStore('lambobudi-dunia-roster-v3',[])))}`);break;
 case 'teacher-refresh':await teacherAction('teacher');break;
 case 'teacher-open':await teacherAction('open');break;
 case 'teacher-close':await teacherAction('close');break;
 case 'teacher-copy':try{await navigator.clipboard.writeText(teacherCode);toast('Kod kelas disalin.');}catch{toast('Kod kelas: '+teacherCode);}break;
 case 'teacher-export':exportCSV();break;
 case 'teacher-delete':openDialog(`<h2>Padam sesi ${esc(teacherCode)}?</h2><p>Semua rekod peserta dan refleksi dalam sesi ini akan dipadam. Muat turun CSV dahulu jika diperlukan.</p>${btn('teacher-confirm-delete','Ya, padam sesi ini')}`);break;
 case 'teacher-confirm-delete':try{await api({action:'delete',teacherKey,code:teacherCode});teacherData=null;teacherCode='';closeDialog();teacher();toast('Sesi telah dipadam.');}catch(e){toast(e.message);}break;
 }}
document.addEventListener('click',e=>{const audio=e.target.closest('[data-audio]');if(audio){speak(audio.dataset.audio,audio);return;}const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();Promise.resolve(action(el.dataset.action,el)).catch(err=>toast(err.message||'Cuba sekali lagi.'));}});
document.addEventListener('submit',e=>{if(e.target.id==='start-form'){e.preventDefault();start(e.target);}if(e.target.id==='teacher-form'){e.preventDefault();teacherSubmit(e.target,e.submitter?.value||'teacher');}});
document.addEventListener('change',e=>{const key=e.target.dataset.setting;if(!key)return;settings[key]=e.target.type==='checkbox'?e.target.checked:['font','spacing','rate'].includes(key)?Number(e.target.value):e.target.value;applySettings();if(key==='syllables')readingRefresh=true;if(race){race.reduced=settings.reduced;}});
$('#close-dialog').onclick=closeDialog;dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#brand').onclick=e=>{e.preventDefault();navigate('home');};$('#help-btn').onclick=help;$('#settings-btn').onclick=settingsDialog;$('#teacher-btn').onclick=()=>navigate('teacher');$('#sources-btn').onclick=about;
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech();if(document.hidden&&race)race.pause();});
window.addEventListener('pagehide',()=>{save();stopSpeech();});
applySettings();home();
